package com.trampolim.api.career;
import java.util.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController public class CareerAccountController {
 private final JdbcTemplate jdbc;private final SkillCatalog users;private final RadarBridge json;public CareerAccountController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog users,RadarBridge json){this.jdbc=jdbc;this.users=users;this.json=json;}
 @DeleteMapping("/api/career/interviews/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal String email,@PathVariable UUID id){if(jdbc.update("DELETE FROM career_interview_sessions WHERE id=? AND user_id=?",id,users.user(email))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
 @GetMapping("/api/career/account/export")public Map<String,Object> export(@AuthenticationPrincipal String email){long uid=users.user(email);var out=new LinkedHashMap<String,Object>();out.put("interviews",rows("SELECT id,area,occupation,questions,answers,feedback,completed_at,created_at FROM career_interview_sessions WHERE user_id=?",uid));out.put("projects",rows("SELECT receipt_id,challenge_id,alias,body,project_url,consent_at,withdrawn_at FROM career_challenge_submissions WHERE user_id=?",uid));out.put("portfolio",rows("SELECT id,kind,title,description,url,created_at FROM career_portfolio_items WHERE user_id=?",uid));out.put("shares",rows("SELECT id,recipient_email,alias,item_ids,evidence_receipts,expires_at,revoked_at,consent_at FROM career_portfolio_shares WHERE user_id=?",uid));out.put("plans",rows("SELECT step,notes,updated_at FROM career_first_job_steps WHERE user_id=?",uid));out.put("regionalConsent",rows("SELECT region_code,consent_at FROM career_observatory_consents WHERE user_id=?",uid));out.put("satisfaction",rows("SELECT rating,updated_at FROM career_satisfaction WHERE user_id=?",uid));out.put("aiUsage",rows("SELECT topic,status,reserved_tokens,input_tokens,output_tokens,estimated_usd,result,created_at FROM career_ai_requests WHERE user_id=?",uid));return out;}
 private List<Map<String,Object>> rows(String sql,long uid){var rows=jdbc.queryForList(sql,uid);for(var row:rows)for(var entry:row.entrySet())if(entry.getValue()!=null&&Set.of("questions","answers","feedback","item_ids","evidence_receipts","result").contains(entry.getKey()))entry.setValue(json.convert(json.read(entry.getValue()),Object.class));return rows;}
}
